 _offerIguanaPlayDead(pid){const p=this._state.players[pid],t=p?.superstar?.ability?.trigger??{};if(t.type!=='iguanaPlayDead'||p.abilityUses>=(t.maxUses??1))return false;return this._offerTriggeredAbility(pid,'iguanaPlayDead',p.superstar.ability.name,'after an opponent grounded Mr. Iguana',use=>{if(!use)return;p.abilityUses++;p.abilityUsed=true;if(t.draw)this._draw(pid,t.draw);if(t.adrenaline)this._ad(pid,t.adrenaline);this._log('SUPERSTAR_ABILITY',{playerId:pid,abilityName:p.superstar.ability.name,use:p.abilityUses,maxUses:t.maxUses??1,effect:'play-dead',draw:t.draw??0,adrenaline:t.adrenaline??0});});}
