 _search(pid,name,discount=0){const p=this._state.players[pid];if(!p.deck.length)this._recyclePlaybook(pid);const i=p.deck.findIndex(x=>x.name===name);if(i<0)return null;const[c]=p.deck.splice(i,1);p.hand.push(c);if(discount)p.namedDiscount[name]=(p.namedDiscount[name]??0)+discount;this._log("CARDS_DRAWN",{playerId:pid,cardIds:[c.id]});return c;}
